{"file_path":"src/simulate.js","content":"/**
 * Replays parsed events through the routes and policies they resolve to,
 * producing a verdict per event and running per-key and total tallies.
 */

function findRoute(key, routes) {
  let best = null
  for (const [prefix, policyNames] of routes) {
    if (key.startsWith(prefix) && (best === null || prefix.length > best.prefix.length)) {
      best = { prefix, policyNames }
    }
  }
  return best
}

export function simulate({ policies, routes, events }) {
  const verdicts = []
  const perKey = new Map()
  let totalAllowed = 0
  let totalDenied = 0

  for (const { tick, key } of events) {
    const route = findRoute(key, routes)
    let allowed = true
    let denyPolicy = null

    if (route) {
      const chain = route.policyNames.map((name) => ({ name, policy: policies.get(name) }))
      for (const { policy } of chain) policy.advance(key, tick)
      for (const { name, policy } of chain) {
        if (!policy.allow(key)) {
          allowed = false
          denyPolicy = name
          break
        }
      }
      if (allowed) {
        for (const { policy } of chain) policy.record(key, tick)
      }
    }

    verdicts.push({ tick, key, allowed, denyPolicy })

    let stat = perKey.get(key)
    if (!stat) {
      stat = { allowed: 0, denied: 0 }
      perKey.set(key, stat)
    }
    if (allowed) {
      stat.allowed++
      totalAllowed++
    } else {
      stat.denied++
      totalDenied++
    }
  }

  return { verdicts, perKey, totalAllowed, totalDenied }
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { parse, ParseError } from './parser.js'
import { simulate } from './simulate.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('fs')
  let bytesRead
  while (true) {
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (e) {
      if (e.code === 'EAGAIN') continue
      if (e.code === 'EOF') break
      throw e
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }
  const mode = args[0]

  const text = readStdin()

  let model
  try {
    model = parse(text)
  } catch (e) {
    if (e instanceof ParseError) {
      process.stderr.write(`error: line ${e.line}: ${e.message}\n`)
      process.exit(2)
    }
    throw e
  }

  const { verdicts, perKey, totalAllowed, totalDenied } = simulate(model)

  const out = []
  if (mode === 'replay') {
    for (const v of verdicts) {
      if (v.allowed) out.push(`${v.tick} ${v.key} allow\n`)
      else out.push(`${v.tick} ${v.key} deny ${v.denyPolicy}\n`)
    }
  } else {
    const keys = [...perKey.keys()].sort()
    for (const key of keys) {
      const stat = perKey.get(key)
      out.push(`${key} allowed=${stat.allowed} denied=${stat.denied}\n`)
    }
    out.push(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
  }
  process.stdout.write(out.join(''))
  process.exit(0)
}

main()
"}

