  const line = ctx.line
  let pos = ctx.pos + 1
  let out = ''
  while (true) {
    if (pos >= line.length) throw new DocError('unterminated string')
    const c = line[pos]
    if (c === '"') {
      ctx.pos = pos + 1
      return out
    }
    if (c === '\\') {
      pos++
      if (pos >= line.length) throw new DocError('unterminated string')
      const e = line[pos]
      if (e === '"') {
        out += '"'
        pos++
      } else if (e === '\\') {
        out += '\\'
        pos++
      } else if (e === 'n') {
        out += '\n'
        pos++
      } else if (e === 't') {
        out += '\t'
        pos++
      } else if (e === 'r') {
        out += '\r'
        pos++
      } else if (e === '0') {
        out += '\0'
        pos++
      } else if (e === 'u') {
        const hex = line.slice(pos + 1, pos + 5)
        if (hex.length === 4 && /^[0-9a-fA-F]{4}$/.test(hex)) {
          out += String.fromCharCode(parseInt(hex, 16))
          pos += 5
        } else {
          throw new DocError('invalid escape \\u')
        }
      } else {
        throw new DocError(`invalid escape \\${e}`)
      }
