{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-7yZ5Ie/src/parser.js","content":"/**
 * Turns a configuration document into a document tree (see `model.js` for
 * the node shapes). Splits the input into lines, skips blank and
 * comment-only lines, and dispatches every other line to either a table
 * header (`[name]` / `[[name]]`) or a `<dotted name> = <value>` assignment.
 */

import { DocError, LineError } from './errors.js'
import { makeTable, makeArrayOfTables, resolveContainer, assignDotted, formatPath } from './model.js'
import { parseDottedName, parseValue, skipWsAndComment } from './values.js'

function processHeader(ctx, root, current) {
  ctx.pos++ // skip the first '['
  let isArray = false
  if (ctx.pos < ctx.line.length && ctx.line[ctx.pos] === '[') {
    isArray = true
    ctx.pos++
  }
  const names = parseDottedName(ctx)
  skipWsAndComment(ctx)
  if (ctx.pos >= ctx.line.length || ctx.line[ctx.pos] !== ']') {
    throw new DocError('unterminated table header')
  }
  ctx.pos++
  if (isArray) {
    if (ctx.pos >= ctx.line.length || ctx.line[ctx.pos] !== ']') {
      throw new DocError('unterminated table header')
    }
    ctx.pos++
  }
  skipWsAndComment(ctx)
  if (ctx.pos < ctx.line.length) throw new DocError('trailing text after a table header')

  const { node: parent, path } = resolveContainer(root, [], names)
  const finalName = names[names.length - 1]
  const finalPath = path.concat(finalName)

  if (!isArray) {
    let child = parent.children.get(finalName)
    if (!child) {
      child = makeTable()
      parent.children.set(finalName, child)
    } else if (child.kind !== 'table') {
      throw new DocError(`${formatPath(finalPath)} is not a table`)
    } else if (child.headerDefined) {
      throw new DocError(`table ${formatPath(finalPath)} is defined twice`)
    }
    child.headerDefined = true
    return { currentTable: child, currentPath: finalPath }
  }

  let child = parent.children.get(finalName)
  if (!child) {
    child = makeArrayOfTables()
    parent.children.set(finalName, child)
  } else if (child.kind !== 'arrayOfTables') {
    throw new DocError(`${formatPath(finalPath)} is not an array of tables`)
  }
  const table = makeTable()
  child.items.push(table)
  return { currentTable: table, currentPath: finalPath }
}

function processAssignment(ctx, current) {
  const names = parseDottedName(ctx)
  skipWsAndComment(ctx)
  if (ctx.pos >= ctx.line.length || ctx.line[ctx.pos] !== '=') {
    throw new DocError('expected key = value')
  }
  ctx.pos++
  const val = parseValue(ctx, current.currentPath.concat(names))
  skipWsAndComment(ctx)
  if (ctx.pos < ctx.line.length) throw new DocError('trailing text after a value')
  assignDotted(current.currentTable, names, val, current.currentPath)
}

export function parseDocument(text) {
  const rawLines = text.split('\n')
