  let current = { currentTable: root, currentPath: [] }

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const line = rawLines[i]
    const withoutLeadingWs = line.replace(/^[ \t]*/, '')
    if (withoutLeadingWs === '') continue
    const firstChar = withoutLeadingWs[0]
    if (firstChar === '#' || firstChar === ';') continue

    const ctx = { line, pos: line.length - withoutLeadingWs.length }
