 * The lexer. `tokenize(source)` scans UTF-8 source text (already decoded to a
 * JS string) into a flat list of tokens, or throws a `LexError` at the first
 * character the grammar does not accept.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set(
  ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'],
)

export class LexError extends Error {
  constructor(line, column, reason) {
    super(reason)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

const isDecDigit = (c) => c >= '0' && c <= '9'
const isHexDigit = (c) => (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
const isBinDigit = (c) => c === '0' || c === '1'
const isOctDigit = (c) => c >= '0' && c <= '7'
const isLetter = (c) => (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
const isIdentPart = (c) => isLetter(c) || isDecDigit(c) || c === '_'

function tabStop(column) {
  return (Math.floor((column - 1) / 4) + 1) * 4 + 1
}

/**
 * Splits the source into one entry per Unicode code point, each carrying the
 * line and column it sits at, plus a handful of end-of-input sentinels so
 * lookahead never has to check array bounds.
 */
function positions(source) {
  const entries = []
  let line = 1
  let column = 1
  for (const ch of source) {
    entries.push({ ch, line, column })
    if (ch === '\n') {
      line += 1
