{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-FB7WeN/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { computeMerge } from './merge.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/**
 * Split raw stdin text into lines, dropping the empty tail a trailing
 * newline leaves, then split those lines into exactly three documents on
 * lines that are exactly `%%%`.
 */
function parseDocuments(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }
  if (parts.length !== 3) fail('expected three parts separated by %%%')
  return parts
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  let bytesRead
  do {
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (error) {
      if (error.code === 'EAGAIN') continue
      if (error.code === 'EOF') break
      throw error
    }
    if (bytesRead > 0) chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  } while (bytesRead > 0)
  return Buffer.concat(chunks).toString('utf8')
}

function formatOutput(mode, segments) {
  const outLines = []
  let hadConflict = false
  for (const segment of segments) {
    if (segment.type === 'conflict') {
      hadConflict = true
      outLines.push('<<<<<<< mine', ...segment.mine)
      if (mode === 'merge') outLines.push('||||||| base', ...segment.base)
      outLines.push('=======', ...segment.theirs, '>>>>>>> theirs')
    } else {
      outLines.push(...segment.lines)
    }
  }
  return { text: outLines.length === 0 ? '' : outLines.join('\n') + '\n', hadConflict }
}

function formatRegions(segments) {
  const outLines = []
  let hadConflict = false
  for (const segment of segments) {
    if (segment.type === 'conflict') {
      hadConflict = true
      outLines.push(`conflict mine=${segment.mine.length} base=${segment.base.length} theirs=${segment.theirs.length}`)
    } else {
      outLines.push(`${segment.type} ${segment.lines.length}`)
    }
  }
  return { text: outLines.length === 0 ? '' : outLines.join('\n') + '\n', hadConflict }
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) fail('usage: cli.js merge|merge2|regions')

  const input = readStdin()
  const [mine, base, theirs] = parseDocuments(input)
  const segments = computeMerge(mine, base, theirs)

  const { text, hadConflict } = mode === 'regions' ? formatRegions(segments) : formatOutput(mode, segments)
  process.stdout.write(text)
  process.exit(hadConflict ? 1 : 0)
}

main()
"}

