  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.has(mode)) fail('usage: cli.js merge|merge2|regions')

  const input = readStdin()
  const [mine, base, theirs] = parseDocuments(input)
  const segments = computeMerge(mine, base, theirs)

  const { text, hadConflict } = mode === 'regions' ? formatRegions(segments) : formatOutput(mode, segments)
  process.stdout.write(text)
  process.exit(hadConflict ? 1 : 0)
