{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-GNU9BY/src/uri.js","content":"/**
 * RFC 3986 generic-syntax parsing, percent-encoding normalization, dot-segment
 * removal and reference resolution, independent of any CLI concerns.
 */

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

/** Raised when a component holds a `%` not followed by two hex digits. */
export class TruncatedPercentEncodingError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

/**
 * Splits a URI reference into its five generic-syntax components. Absent
 * components are `undefined`; the path is always a (possibly empty) string.
 */
export function parseReference(ref) {
  let rest = ref
  let scheme

  const stopIdx = (() => {
    for (let i = 0; i < rest.length; i++) {
      const c = rest[i]
      if (c === ':') return i
      if (c === '/' || c === '?' || c === '#') return -1
    }
    return -1
  })()
  if (stopIdx !== -1) {
    scheme = rest.slice(0, stopIdx)
    rest = rest.slice(stopIdx + 1)
  }

  let authority
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    let end = rest.length
    for (let i = 0; i < rest.length; i++) {
      if (rest[i] === '/' || rest[i] === '?' || rest[i] === '#') { end = i; break }
    }
    authority = rest.slice(0, end)
    rest = rest.slice(end)
  }

  let end = rest.length
  for (let i = 0; i < rest.length; i++) {
    if (rest[i] === '?' || rest[i] === '#') { end = i; break }
  }
  const path = rest.slice(0, end)
  rest = rest.slice(end)

  let query
  if (rest.startsWith('?')) {
    let qend = rest.length
    for (let i = 1; i < rest.length; i++) {
      if (rest[i] === '#') { qend = i; break }
    }
    query = rest.slice(1, qend)
    rest = rest.slice(qend)
  }

  let fragment
  if (rest.startsWith('#')) {
    fragment = rest.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

/** Splits an authority into userinfo, host and port, per the task's rules. */
export function parseAuthority(authority) {
  let userinfo
  let hostport = authority
  const lastAt = authority.lastIndexOf('@')
  if (lastAt !== -1) {
    userinfo = authority.slice(0, lastAt)
    hostport = authority.slice(lastAt + 1)
  }

  const lastBracket = hostport.lastIndexOf(']')
  const searchStart = lastBracket + 1
  const colonIdx = hostport.indexOf(':', searchStart)

  let host
  let port
  if (colonIdx === -1) {
    host = hostport
  } else {
    host = hostport.slice(0, colonIdx)
    port = hostport.slice(colonIdx + 1)
  }

  return { userinfo, host, port }
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/

/**
 * Uppercases every `%XX` triplet's hex digits and decodes those that encode
 * an unreserved character. Throws {@link TruncatedPercentEncodingError} when
 * a `%` lacks two following hex digits.
 */
export function normalizePercentEncoding(str, component) {
  let out = ''
  for (let i = 0; i < str.length; i++) {
    const c = str[i]
    if (c !== '%') {
      out += c
      continue
    }
    const hex = str.slice(i + 1, i + 3)
    if (hex.length !== 2 || !/^[0-9a-fA-F]{2}$/.test(hex)) {
      throw new TruncatedPercentEncodingError(component)
    }
    const upper = hex.toUpperCase()
    const ch = String.fromCharCode(parseInt(upper, 16))
    out += UNRESERVED.test(ch) ? ch : `%${upper}`
    i += 2
  }
  return out
}

/** Lowercases ASCII letters only, leaving every other character untouched. */
function lowerAscii(str) {
  return str.replace(/[A-Z]/g, (c) => c.toLowerCase())
}

function removeLastOutputSegment(output) {
  const lastSlash = output.lastIndexOf('/')
  return lastSlash === -1 ? '' : output.slice(0, lastSlash)
}

/** Removes `.` and `..` path segments per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = removeLastOutputSegment(output)
    } else if (input === '/..') {
      input = '/'
      output = removeLastOutputSegment(output)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx
      if (input[0] === '/') {
        idx = input.indexOf('/', 1)
      } else {
        idx = input.indexOf('/')
      }
      if (idx === -1) idx = input.length
      output += input.slice(0, idx)
      input = input.slice(idx)
    }
  }
  return output
}

/**
 * Normalizes a parsed reference in place: lowercases the scheme, normalizes
 * percent-encodings in every component (checking path, userinfo, host, query
 * and fragment in that order), lowercases the host, drops a default or empty
 * port, removes dot segments from the path, and forces `/` when an authority
 * is present with an empty path.
 */
export function normalizeComponents(components) {
  const { scheme, authority, path, query, fragment } = components

  const normScheme = scheme === undefined ? undefined : lowerAscii(scheme)

  const normPath = normalizePercentEncoding(path, 'path')

  let auth
  if (authority !== undefined) {
    const { userinfo, host, port } = parseAuthority(authority)
    const normUserinfo = userinfo === undefined ? undefined : normalizePercentEncoding(userinfo, 'userinfo')
    let normHost = normalizePercentEncoding(host, 'host')
    normHost = lowerAscii(normHost)

    let normPort = port
    if (normPort !== undefined) {
      const defaultPort = normScheme === undefined ? undefined : DEFAULT_PORTS[normScheme]
      if (normPort === '' || normPort === defaultPort) {
        normPort = undefined
      }
    }

    auth = { userinfo: normUserinfo, host: normHost, port: normPort }
  }

  const normQuery = query === undefined ? undefined : normalizePercentEncoding(query, 'query')
  const normFragment = fragment === undefined ? undefined : normalizePercentEncoding(fragment, 'fragment')

  let finalPath = removeDotSegments(normPath)
  if (authority !== undefined && finalPath === '') {
    finalPath = '/'
  }

  return {
    scheme: normScheme,
    authorityParts: auth,
    path: finalPath,
    query: normQuery,
    fragment: normFragment,
  }
}

/** Serializes normalized components back into a URI reference string. */
export function serialize(normalized) {
  let out = ''
  if (normalized.scheme !== undefined) {
    out += normalized.scheme + ':'
  }
  if (normalized.authorityParts !== undefined) {
    const { userinfo, host, port } = normalized.authorityParts
    out += '//'
    if (userinfo !== undefined) out += userinfo + '@'
    out += host
    if (port !== undefined) out += ':' + port
  }
  out += normalized.path
  if (normalized.query !== undefined) {
    out += '?' + normalized.query
  }
  if (normalized.fragment !== undefined) {
    out += '#' + normalized.fragment
  }
  return out
}

/** Parses and normalizes a URI reference, returning its serialized form. */
export function normalizeReference(ref) {
  const parsed = parseReference(ref)
  const normalized = normalizeComponents(parsed)
  return serialize(normalized)
}

function mergePaths(base, refPath) {
  if (base.authority !== undefined && base.path === '') {
    return '/' + refPath
  }
  const lastSlash = base.path.lastIndexOf('/')
  if (lastSlash === -1) {
    return refPath
  }
  return base.path.slice(0, lastSlash + 1) + refPath
}

/**
 * Resolves a reference against a base, both already parsed, per RFC 3986
 * section 5.2.2 (strict). Returns a parsed-components object; dot-segment
 * removal for the merged path happens here, final normalization does not.
 */
export function resolveComponents(base, ref) {
  let target

  if (ref.scheme !== undefined) {
    target = {
      scheme: ref.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
    }
  } else if (ref.authority !== undefined) {
    target = {
      scheme: base.scheme,
      authority: ref.authority,
      path: removeDotSegments(ref.path),
      query: ref.query,
    }
  } else if (ref.path === '') {
    target = {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: ref.query !== undefined ? ref.query : base.query,
    }
  } else {
    let path
    if (ref.path.startsWith('/')) {
      path = removeDotSegments(ref.path)
    } else {
      path = removeDotSegments(mergePaths(base, ref.path))
    }
    target = {
      scheme: base.scheme,
      authority: base.authority,
      path,
      query: ref.query,
    }
  }

  target.fragment = ref.fragment
  return target
}

/** Parses, resolves and normalizes a reference against a base string. */
export function resolveReference(baseStr, refStr) {
  const base = parseReference(baseStr)
  const ref = parseReference(refStr)
  const resolved = resolveComponents(base, ref)
  const normalized = normalizeComponents(resolved)
  return serialize(normalized)
}

export { DEFAULT_PORTS }
"}

