/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { CliError, normalizeUri, resolveUri } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
  fail('usage: cli.js normalize|resolve')
}

const input = readFileSync(0, 'utf8')
let lines = input.split('\n')
if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

const results = []
for (let i = 0; i < lines.length; i++) {
  const lineNo = i + 1
  const line = lines[i]
  try {
    if (mode === 'normalize') {
      results.push(normalizeUri(line))
    } else {
      const spaceIdx = line.indexOf(' ')
      if (spaceIdx === -1) {
        throw new CliError('expected a base and a reference')
      }
      const base = line.slice(0, spaceIdx)
      const ref = line.slice(spaceIdx + 1)
      results.push(resolveUri(base, ref))
    }
  } catch (err) {
    if (err instanceof CliError) {
      fail(`line ${lineNo}: ${err.message}`)
    }
    throw err
  }
}

process.stdout.write(results.length ? results.join('\n') + '\n' : '')
process.exit(0)
"}

