 * Error types the CLI distinguishes when choosing an exit code:
 * `CliError` for the ordinary "one line to stderr, exit 2" failures, and
 * `CycleError` for the "error: cycle: ..." case that exits 3.
 */

export class CliError extends Error {}

export class CycleError extends Error {
  constructor(names) {
    super(`cycle: ${names.join(' -> ')}`)
    this.names = names
  }
}
"}

