{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-RUFa9n/src/pack.js","content":"/**
 * Simulates the build graph running on a fixed number of workers, greedily
 * starting the highest-priority ready task on the lowest-index free worker
 * at every instant.
 */

import { computePriority } from './graph.js'

export function pack(tasks, workerCount) {
  const priority = computePriority(tasks)
  const remaining = new Set(tasks.keys())
  const finishTime = new Map()
  const workerFreeAt = new Array(workerCount).fill(0)
  const workerLog = Array.from({ length: workerCount }, () => [])

  let time = 0
  while (remaining.size > 0) {
    let assigned = true
    while (assigned) {
      assigned = false

      let workerIndex = -1
      for (let i = 0; i < workerCount; i++) {
        if (workerFreeAt[i] <= time) {
          workerIndex = i
          break
        }
      }
      if (workerIndex === -1) break

      const ready = [...remaining].filter((name) =>
        [...tasks.get(name).deps].every((dep) => finishTime.get(dep) <= time),
      )
      if (ready.length === 0) break

      ready.sort((a, b) => priority.get(b) - priority.get(a) || (a < b ? -1 : 1))
      const chosen = ready[0]
      const cost = tasks.get(chosen).cost
      const finish = time + cost

      workerLog[workerIndex].push({ name: chosen, start: time, finish })
      workerFreeAt[workerIndex] = finish
      finishTime.set(chosen, finish)
      remaining.delete(chosen)
      assigned = true
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerFreeAt[i] > time) next = Math.min(next, workerFreeAt[i])
    }
    time = next
  }

  return workerLog
}
"}

