{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-RUFa9n/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { parseGraph } from './parse.js'
import { checkForCycle, computeSchedule } from './graph.js'
import { pack } from './pack.js'
import { CliError, CycleError } from './errors.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) {
      throw new CliError('workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE.slice('error: '.length))
}

function formatWaves(tasks, schedule) {
  const names = [...tasks.keys()].sort()
  const byDepth = new Map()
  let total = 0
  for (const name of names) {
    const { depth, finish } = schedule.get(name)
    if (!byDepth.has(depth)) byDepth.set(depth, [])
    byDepth.get(depth).push(name)
    total = Math.max(total, finish)
  }
  const lines = []
  const maxDepth = byDepth.size === 0 ? -1 : Math.max(...byDepth.keys())
  for (let depth = 0; depth <= maxDepth; depth++) {
    lines.push(`wave ${depth}: ${byDepth.get(depth).join(' ')}`)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function formatExplain(tasks, schedule) {
  const names = [...tasks.keys()].sort()
  let total = 0
  const lines = []
  for (const name of names) {
    const { start, finish, depth } = schedule.get(name)
    total = Math.max(total, finish)
    lines.push(`${name} start=${start} finish=${finish} depth=${depth}`)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function formatPack(tasks, workerCount) {
  const workerLog = pack(tasks, workerCount)
  let makespan = 0
  const lines = []
  for (let i = 0; i < workerCount; i++) {
