/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { run } from './limiter.js'

const mode = process.argv[2]
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const chunks = []
for await (const chunk of process.stdin) chunks.push(chunk)
const input = chunks.join('')

const result = run(input, mode)
if (!result.ok) {
  process.stderr.write(`error: ${result.message}\n`)
  process.exit(2)
}

process.stdout.write(result.output)
process.exit(0)
"}

