export function computePriorities(costs, dependents) {
  const priorities = new Map()

  function priorityFor(name) {
    const cached = priorities.get(name)
    if (cached !== undefined) return cached
    let best = 0
    for (const dependent of dependents.get(name) ?? []) {
      const dependentPriority = priorityFor(dependent)
      if (dependentPriority > best) best = dependentPriority
    }
    const priority = costs.get(name) + best
    priorities.set(name, priority)
    return priority
  }

  for (const name of costs.keys()) priorityFor(name)
  return priorities
