 * Shared by both `values` and `deps` so parsing rules live in one place.
 */

import { tokenize, FormulaError } from './lexer.js'
import { parseFormula } from './parser.js'
import { num, text, err, ERROR_TOKENS } from './values.js'

const NUMBER_LITERAL_RE = /^-?[0-9]+(\.[0-9]+)?$/

/** Parses a non-formula cell's content into a literal value. */
export function parseLiteral(content) {
  if (content === '') return num(0)
  if (NUMBER_LITERAL_RE.test(content)) return num(parseFloat(content))
  if (ERROR_TOKENS.includes(content)) return err(content)
  return text(content)
}

/**
 * Parses a cell's content, returning `{ kind: 'literal', value }` or
 * `{ kind: 'formula', ast }` (`ast` is null when the grammar rejects it).
 */
export function parseContent(content) {
  if (!content.startsWith('=')) {
    return { kind: 'literal', value: parseLiteral(content) }
  }
  try {
    const tokens = tokenize(content.slice(1))
    const ast = parseFormula(tokens)
    return { kind: 'formula', ast }
  } catch (e) {
    if (e instanceof FormulaError) return { kind: 'formula', ast: null }
    throw e
  }
}
