{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-pBamUh/src/evaluator.js","content":"/**
 * Evaluates cell content into values, resolving cell references and
 * detecting cycles as a lazy, memoized walk of each cell's formula AST.
 *
 * Cycle detection: a cell currently being evaluated is "visiting"; reaching
 * a visiting cell again yields a transient `#CYCLE!` value rather than
 * recursing further. That transient value then flows through the ordinary
 * error-propagation rules like any other error, so every cell actually on
 * the cycle ends up caching `#CYCLE!` for itself once its own evaluation
 * (which needed to reach back around to itself) completes.
 */

import { parseAddress, compareAddresses } from './address.js'
import { parseContent } from './formula.js'
import { num, bool, err, isErr, toNumber, checkFinite, compareValues } from './values.js'

const AGGREGATE_FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

export class EvalContext {
  constructor(sheet) {
    this.sheet = sheet
    this.cache = new Map()
    this.visiting = new Set()
    this.parsed = new Map() // memoized parseContent results by cell key
  }

  contentOf(key) {
    if (this.parsed.has(key)) return this.parsed.get(key)
    const cell = this.sheet.cells.get(key)
    const parsed = parseContent(cell.content)
    this.parsed.set(key, parsed)
    return parsed
  }

  evalAddress(key) {
    if (this.cache.has(key)) return this.cache.get(key)
    if (this.visiting.has(key)) return err('#CYCLE!')
    if (!this.sheet.cells.has(key)) {
      const value = num(0)
      this.cache.set(key, value)
      return value
    }
    this.visiting.add(key)
    const parsed = this.contentOf(key)
    const value = parsed.kind === 'literal' ? parsed.value : evalFormula(parsed.ast, this)
    this.visiting.delete(key)
    this.cache.set(key, value)
    return value
  }
}

function evalFormula(ast, ctx) {
  if (ast === null) return err('#ERR!')
  return evalExpr(ast, ctx)
}

/** Expands a range's from/to corners into an ordered list of address keys, or null. */
function expandRange(node) {
  const from = parseAddress(node.from)
  const to = parseAddress(node.to)
  if (!from || !to) return null
  const colMin = Math.min(from.col, to.col)
  const colMax = Math.max(from.col, to.col)
  const rowMin = Math.min(from.row, to.row)
  const rowMax = Math.max(from.row, to.row)
  const keys = []
  for (let col = colMin; col <= colMax; col++) {
    for (let row = rowMin; row <= rowMax; row++) {
      keys.push(colRowToKey(col, row))
    }
  }
  return keys
}

function colRowToKey(col, row) {
  let letters = ''
  let n = col
  while (n > 0) {
    n -= 1
    letters = String.fromCharCode(65 + (n % 26)) + letters
    n = Math.floor(n / 26)
  }
  return `${letters}${row}`
}

/** Evaluates a single AST node as a plain (non-argument) expression. */
function evalExpr(node, ctx) {
  switch (node.type) {
    case 'Number':
      return num(node.value)
    case 'Bool':
      return bool(node.value)
    case 'Address': {
      const addr = parseAddress(node.text)
      if (!addr) return err('#REF!')
      return ctx.evalAddress(addr.key)
    }
    case 'Range':
      // A range not used directly as a function argument is misplaced.
      return err('#ERR!')
    case 'Unary':
      return evalUnary(node, ctx)
    case 'BinOp':
      return evalBinOp(node, ctx)
    case 'Call':
      return evalCall(node, ctx)
    default:
      throw new Error(`unknown node type: ${node.type}`)
  }
}

function evalUnary(node, ctx) {
  const inner = evalExpr(node.expr, ctx)
  if (isErr(inner)) return inner
  const n = toNumber(inner)
  if (isErr(n)) return n
  return checkFinite(node.op === 'MINUS' ? -n.v : n.v)
}

const COMPARISON_OPS = {
  EQ: (c) => c === 0,
  NE: (c) => c !== 0,
  LT: (c) => c < 0,
  LE: (c) => c <= 0,
  GT: (c) => c > 0,
  GE: (c) => c >= 0,
}

const ARITHMETIC_OPS = {
  PLUS: (a, b) => a + b,
  MINUS: (a, b) => a - b,
  STAR: (a, b) => a * b,
  SLASH: (a, b) => a / b,
  CARET: (a, b) => Math.pow(a, b),
}

function evalBinOp(node, ctx) {
  const left = evalExpr(node.left, ctx)
  if (isErr(left)) return left
  const right = evalExpr(node.right, ctx)
  if (isErr(right)) return right

  if (node.op in COMPARISON_OPS) {
    return bool(COMPARISON_OPS[node.op](compareValues(left, right)))
  }

  const leftNum = toNumber(left)
  if (isErr(leftNum)) return leftNum
  const rightNum = toNumber(right)
  if (isErr(rightNum)) return rightNum
  return checkFinite(ARITHMETIC_OPS[node.op](leftNum.v, rightNum.v))
}

/** Evaluates a call argument, expanding a range into every cell it covers. */
function evalArgItems(node, ctx) {
  if (node.type === 'Range') {
    const keys = expandRange(node)
    if (keys === null) return [err('#REF!')]
    return keys.map((key) => ctx.evalAddress(key))
  }
  return [evalExpr(node, ctx)]
}

function firstError(items) {
  return items.find(isErr) ?? null
}

function evalCall(node, ctx) {
  const name = node.name
  if (name === 'IF') return evalIf(node, ctx)
  if (name === 'ABS') return evalAbs(node, ctx)
  if (AGGREGATE_FUNCTIONS.has(name)) return evalAggregate(name, node, ctx)
  return err('#NAME?')
}

function evalAbs(node, ctx) {
  if (node.args.length !== 1) return err('#ERR!')
  const items = evalArgItems(node.args[0], ctx)
  const e = firstError(items)
  if (e) return e
  const n = toNumber(items[0])
  if (isErr(n)) return n
  return checkFinite(Math.abs(n.v))
}

function evalIf(node, ctx) {
  if (node.args.length !== 3) return err('#ERR!')
  const condItems = evalArgItems(node.args[0], ctx)
  const condErr = firstError(condItems)
  if (condErr) return condErr
  const condNum = toNumber(condItems[0])
  if (isErr(condNum)) return condNum

  // The branch not taken is never evaluated, so an error or cycle there is invisible.
  const branch = condNum.v !== 0 ? node.args[1] : node.args[2]
  const branchItems = evalArgItems(branch, ctx)
  const branchErr = firstError(branchItems)
  if (branchErr) return branchErr
  return branchItems[0]
}

function evalAggregate(name, node, ctx) {
  if (node.args.length < 1) return err('#ERR!')
  const items = node.args.flatMap((arg) => evalArgItems(arg, ctx))
  const e = firstError(items)
  if (e) return e

  if (name === 'COUNT') {
    return num(items.filter((v) => v.t === 'num').length)
  }

  const nums = []
  for (const item of items) {
    const n = toNumber(item)
    if (isErr(n)) return n
    nums.push(n.v)
  }

  if (name === 'SUM') return checkFinite(nums.reduce((a, b) => a + b, 0))
  if (name === 'AVG') return checkFinite(nums.reduce((a, b) => a + b, 0) / nums.length)
  if (name === 'MIN') return num(Math.min(...nums))
  if (name === 'MAX') return num(Math.max(...nums))
  throw new Error(`unknown aggregate: ${name}`)
}

/** Collects every distinct in-range address a formula AST names directly, ordered. */
export function collectDeps(ast) {
  const found = new Map()
  function visitAddress(text) {
    const addr = parseAddress(text)
    if (addr) found.set(addr.key, addr)
  }
  function visit(node) {
    switch (node.type) {
      case 'Number':
      case 'Bool':
        return
      case 'Address':
        visitAddress(node.text)
        return
      case 'Range': {
        const keys = expandRange(node)
        if (keys) for (const key of keys) visitAddress(key)
        return
      }
      case 'Unary':
        visit(node.expr)
        return
      case 'BinOp':
        visit(node.left)
        visit(node.right)
        return
      case 'Call':
        for (const arg of node.args) visit(arg)
        return
      default:
        throw new Error(`unknown node type: ${node.type}`)
    }
  }
  if (ast) visit(ast)
  return [...found.values()].sort(compareAddresses)
}
