 * Recursive-descent parser for a formula body, producing an AST.
 *
 * Precedence, loosest to tightest: comparisons, then `+`/`-`, then `*`/`/`,
 * then `^`, then a leading unary `-`/`+`. The comparison and additive and
 * multiplicative operators are left-associative; `^` is right-associative;
 * a leading sign binds tighter than `^`.
 *
 * A range (`WORD ':' WORD`) parses wherever an address could appear, so that
 * a range written outside a direct function-argument position is a grammar
 * success whose misuse becomes a runtime `#ERR!` rather than a parse failure.
 */

import { tokenize } from './lexer.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class SyntaxErr extends Error {}

/** Parse a formula body into an AST, or return null if the grammar rejects it. */
export function parseFormula(body) {
  const tokens = tokenize(body)
  if (tokens === null) return null
  try {
    let pos = 0
    const peek = () => tokens[pos]
    const next = () => tokens[pos++]
    const expect = (type) => {
      const t = peek()
      if (!t || t.type !== type) throw new SyntaxErr()
      return next()
    }

    function parseExpr() {
      return parseComparison()
    }

    function parseComparison() {
      let left = parseAdditive()
      while (peek() && peek().type === 'OP' && COMPARISON_OPS.has(peek().value)) {
        const op = next().value
        const right = parseAdditive()
        left = { type: 'binop', op, left, right }
      }
      return left
    }

    function parseAdditive() {
      let left = parseMultiplicative()
      while (peek() && peek().type === 'OP' && (peek().value === '+' || peek().value === '-')) {
        const op = next().value
        const right = parseMultiplicative()
        left = { type: 'binop', op, left, right }
      }
      return left
    }

    function parseMultiplicative() {
      let left = parsePower()
      while (peek() && peek().type === 'OP' && (peek().value === '*' || peek().value === '/')) {
        const op = next().value
        const right = parsePower()
        left = { type: 'binop', op, left, right }
      }
      return left
    }

    function parsePower() {
      const left = parseUnary()
      if (peek() && peek().type === 'OP' && peek().value === '^') {
        next()
        const right = parsePower()
        return { type: 'binop', op: '^', left, right }
      }
      return left
    }

    function parseUnary() {
      if (peek() && peek().type === 'OP' && (peek().value === '-' || peek().value === '+')) {
        const op = next().value
        const operand = parseUnary()
        return { type: 'unary', op, operand }
      }
      return parsePrimary()
    }

    function parseArguments() {
      const args = []
      if (peek() && peek().type === 'RP') return args
      args.push(parseExpr())
      while (peek() && peek().type === 'COMMA') {
        next()
        args.push(parseExpr())
      }
      return args
    }

    function parsePrimary() {
      const t = peek()
      if (!t) throw new SyntaxErr()
      if (t.type === 'NUMBER') {
        next()
        return { type: 'number', value: parseFloat(t.value) }
      }
      if (t.type === 'LP') {
        next()
        const e = parseExpr()
        expect('RP')
        return e
      }
      if (t.type === 'WORD') {
        next()
        const upper = t.value.toUpperCase()
        if (peek() && peek().type === 'LP') {
          next()
          const args = parseArguments()
          expect('RP')
          return { type: 'call', name: upper, args }
        }
        if (upper === 'TRUE') return { type: 'bool', value: true }
        if (upper === 'FALSE') return { type: 'bool', value: false }
        if (peek() && peek().type === 'COLON') {
          next()
          const t2 = expect('WORD')
          return { type: 'range', from: t.value, to: t2.value }
        }
        return { type: 'address', word: t.value }
      }
      throw new SyntaxErr()
    }

    const result = parseExpr()
    if (pos !== tokens.length) throw new SyntaxErr()
    return result
  } catch (e) {
    if (e instanceof SyntaxErr) return null
    throw e
  }
}
"}

