 * Static dependency listing: which cells a formula names directly, without
 * evaluating anything. A formula the grammar rejects, and a plain literal,
 * name nothing.
 */

import { classifyWord, expandRange } from './address.js'
import { parseFormula } from './parser.js'
import { sortedKeys } from './evaluate.js'

function collect(node, set) {
  switch (node.type) {
    case 'number':
    case 'bool':
      return
    case 'address': {
      const info = classifyWord(node.word)
      if (info.inRange) set.add(info.key)
      return
    }
    case 'range': {
      const cells = expandRange(node.from, node.to)
      if (cells !== null) for (const c of cells) set.add(c)
      return
    }
    case 'unary':
      collect(node.operand, set)
      return
    case 'binop':
      collect(node.left, set)
      collect(node.right, set)
      return
    case 'call':
      for (const a of node.args) collect(a, set)
      return
  }
}

/** Render `<address>: <dep1> <dep2> ...` lines for every declared cell. */
export function computeDeps(sheet) {
  let out = ''
  for (const key of sortedKeys(sheet)) {
    const cell = sheet.get(key)
    const set = new Set()
    if (cell.content[0] === '=') {
      if (cell.ast === undefined) cell.ast = parseFormula(cell.content.slice(1))
      if (cell.ast !== null) collect(cell.ast, set)
    }
    const list = [...set].sort((a, b) => {
      const ca = classifyWord(a)
      const cb = classifyWord(b)
      if (ca.col !== cb.col) return ca.col - cb.col
      return ca.row - cb.row
    })
    out += `${key}:` + list.map((a) => ' ' + a).join('') + '\n'
  }
  return out
}
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-vIsrQc/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet, SheetError } from './sheet.js'
import { evaluateAll } from './evaluate.js'
import { computeDeps } from './deps.js'

const mode = process.argv[2]
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

let input = ''
process.stdin.setEncoding('utf8')
for await (const chunk of process.stdin) input += chunk

try {
  const sheet = parseSheet(input)
  const output = mode === 'values' ? evaluateAll(sheet) : computeDeps(sheet)
  process.stdout.write(output)
} catch (e) {
  if (e instanceof SheetError) {
    process.stderr.write(e.message + '\n')
    process.exit(2)
  }
  throw e
}
"}

