 * A hand-rolled scanner for the toy language described in the task. It walks
 * the source text one Unicode code point at a time, tracking a 1-based line
 * and column, and yields tokens or throws a `LexError` at the first
 * malformed construct.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.',
])

function isDecDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}
function isHexDigit(c) {
  return c !== undefined && /[0-9a-fA-F]/.test(c)
}
function isBinDigit(c) {
  return c === '0' || c === '1'
}
function isOctDigit(c) {
  return c !== undefined && c >= '0' && c <= '7'
}
function isIdentStart(c) {
  return c !== undefined && /[A-Za-z_]/.test(c)
}
function isIdentPart(c) {
  return c !== undefined && /[A-Za-z0-9_]/.test(c)
}

export class LexError extends Error {
  constructor(line, col, reason) {
    super(`${line}:${col}: ${reason}`)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

class Scanner {
  constructor(text) {
    this.chars = Array.from(text)
    this.i = 0
    this.line = 1
    this.col = 1
  }

  eof() {
    return this.i >= this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.i + offset]
  }

  advance() {
    const c = this.chars[this.i]
    this.i++
    if (c === '\n') {
      this.line++
      this.col = 1
    } else if (c === '\t') {
      this.col = this.col + (4 - ((this.col - 1) % 4))
    } else {
      this.col++
    }
    return c
  }

  skipTrivia() {
    while (!this.eof()) {
      const c = this.peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        while (!this.eof() && this.peek() !== '\n') this.advance()
        continue
      }
      if (c === '/' && this.peek(1) === '*') {
        const bl = this.line
        const bc = this.col
        this.advance()
        this.advance()
        let depth = 1
        while (depth > 0) {
          if (this.eof()) throw new LexError(bl, bc, 'unterminated block comment')
          const cc = this.peek()
          if (cc === '/' && this.peek(1) === '*') {
            this.advance()
            this.advance()
            depth++
            continue
          }
          if (cc === '*' && this.peek(1) === '/') {
            this.advance()
            this.advance()
            depth--
            continue
          }
          this.advance()
        }
        continue
      }
      break
    }
  }

  // Consumes a run of digits accepted by `digitFn`, allowing a single `_`
  // between two digits of the run. Returns the number of digits consumed
  // (not counting underscores).
  consumeDigitRun(digitFn) {
    let count = 0
    while (!this.eof()) {
      const c = this.peek()
      if (digitFn(c)) {
        this.advance()
        count++
        continue
      }
      if (c === '_' && count > 0 && digitFn(this.peek(1))) {
        this.advance()
        continue
      }
      break
    }
    return count
  }

  identToken() {
    const line = this.line
    const col = this.col
    let text = ''
    while (!this.eof() && isIdentPart(this.peek())) text += this.advance()
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { line, col, kind, text }
  }

  numberToken() {
    const line = this.line
    const col = this.col
    const startIdx = this.i
    const c0 = this.peek()
    let valid = true

    if (c0 === '0' && (this.peek(1) === 'x' || this.peek(1) === 'X')) {
      this.advance()
      this.advance()
      valid = this.consumeDigitRun(isHexDigit) > 0
    } else if (c0 === '0' && (this.peek(1) === 'b' || this.peek(1) === 'B')) {
      this.advance()
      this.advance()
      valid = this.consumeDigitRun(isBinDigit) > 0
    } else if (c0 === '0' && (this.peek(1) === 'o' || this.peek(1) === 'O')) {
      this.advance()
      this.advance()
      valid = this.consumeDigitRun(isOctDigit) > 0
    } else {
      this.consumeDigitRun(isDecDigit)
      if (this.peek() === '.' && isDecDigit(this.peek(1))) {
        this.advance()
        this.consumeDigitRun(isDecDigit)
      }
      if (this.peek() === 'e' || this.peek() === 'E') {
        let hasSign = false
        if ((this.peek(1) === '+' || this.peek(1) === '-') && isDecDigit(this.peek(2))) {
          hasSign = true
        }
        if (isDecDigit(this.peek(1)) || hasSign) {
          this.advance()
          if (hasSign) this.advance()
          this.consumeDigitRun(isDecDigit)
        }
      }
    }

    let hasTrailing = false
    while (!this.eof() && isIdentPart(this.peek())) {
      this.advance()
      hasTrailing = true
    }

    const text = this.chars.slice(startIdx, this.i).join('')
    if (!valid || hasTrailing) {
      throw new LexError(line, col, `invalid number ${text}`)
    }
    return { line, col, kind: 'number', text }
  }

  stringToken() {
    const line = this.line
    const col = this.col
    this.advance() // opening quote
    let value = ''
    while (true) {
      if (this.eof()) throw new LexError(line, col, 'unterminated string')
      const c = this.peek()
      if (c === '"') {
        this.advance()
        break
      }
      if (c === '\n') throw new LexError(this.line, this.col, 'newline in string')
      if (c === '\\') {
        const bl = this.line
        const bc = this.col
        this.advance() // backslash
        if (this.eof()) throw new LexError(line, col, 'unterminated string')
        const e = this.peek()
        if (e === 'n') {
          value += '\n'
          this.advance()
        } else if (e === 't') {
          value += '\t'
          this.advance()
        } else if (e === 'r') {
          value += '\r'
          this.advance()
        } else if (e === '\\') {
          value += '\\'
          this.advance()
        } else if (e === '"') {
          value += '"'
          this.advance()
        } else if (e === '0') {
          value += '\0'
          this.advance()
        } else if (e === 'x') {
          this.advance()
          const h1 = this.peek()
          const h2 = this.peek(1)
          if (!isHexDigit(h1) || !isHexDigit(h2)) throw new LexError(bl, bc, 'invalid escape \\x')
          this.advance()
          this.advance()
          value += String.fromCharCode(parseInt(h1 + h2, 16))
        } else if (e === 'u') {
          this.advance()
          if (this.peek() !== '{') throw new LexError(bl, bc, 'invalid escape \\u')
          this.advance()
          let hex = ''
          while (!this.eof() && isHexDigit(this.peek())) hex += this.advance()
          if (hex.length === 0) throw new LexError(bl, bc, 'invalid escape \\u')
          if (this.eof() || this.peek() !== '}') throw new LexError(bl, bc, 'invalid escape \\u')
          this.advance()
          const code = parseInt(hex, 16)
          if (code > 0x10ffff) throw new LexError(bl, bc, 'invalid escape \\u')
          value += String.fromCodePoint(code)
        } else {
          throw new LexError(bl, bc, `invalid escape \\${e}`)
        }
        continue
      }
      value += c
      this.advance()
    }
    return { line, col, kind: 'string', text: value }
  }

  rawStringToken() {
    const line = this.line
    const col = this.col
    this.advance() // r
    this.advance() // opening quote
    let value = ''
    while (true) {
      if (this.eof()) throw new LexError(line, col, 'unterminated string')
      const c = this.peek()
      if (c === '"') {
        this.advance()
        break
      }
      value += c
      this.advance()
    }
    return { line, col, kind: 'rawstring', text: value }
  }

  punctToken() {
    const line = this.line
    const col = this.col
    const c = this.peek()
    const next = this.peek(1)
    const two = next === undefined ? c : c + next
    if (TWO_CHAR_PUNCT.has(two)) {
      this.advance()
      this.advance()
      return { line, col, kind: 'punct', text: two }
    }
    if (ONE_CHAR_PUNCT.has(c)) {
      this.advance()
      return { line, col, kind: 'punct', text: c }
    }
    throw new LexError(line, col, `unexpected character ${c}`)
  }
}

export function tokenize(text) {
  const scanner = new Scanner(text)
  const tokens = []
  while (true) {
    scanner.skipTrivia()
    if (scanner.eof()) break
    const c = scanner.peek()
    if (c === '"') {
      tokens.push(scanner.stringToken())
    } else if (c === 'r' && scanner.peek(1) === '"') {
      tokens.push(scanner.rawStringToken())
    } else if (isIdentStart(c)) {
      tokens.push(scanner.identToken())
    } else if (isDecDigit(c)) {
      tokens.push(scanner.numberToken())
    } else {
      tokens.push(scanner.punctToken())
    }
  }
  return tokens
}
